CREATE DATABASE IF NOT EXISTS corpo_agregados CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE corpo_agregados;
CREATE TABLE IF NOT EXISTS combustible_despachos (id INT AUTO_INCREMENT PRIMARY KEY,fecha DATE NOT NULL,vehiculo VARCHAR(150) NOT NULL,responsable VARCHAR(150),galones DECIMAL(10,2) NOT NULL,precio DECIMAL(10,2) NOT NULL,total DECIMAL(12,2) NOT NULL,factura VARCHAR(100),observaciones TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ventas (id INT AUTO_INCREMENT PRIMARY KEY,fecha DATE NOT NULL,cliente VARCHAR(180) NOT NULL,producto VARCHAR(100) NOT NULL,cantidad_m3 DECIMAL(10,2) NOT NULL,precio_m3 DECIMAL(10,2) NOT NULL,total DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS produccion (id INT AUTO_INCREMENT PRIMARY KEY,fecha DATE NOT NULL,producto VARCHAR(100) NOT NULL,cantidad_m3 DECIMAL(10,2) NOT NULL,observaciones TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS despachos (id INT AUTO_INCREMENT PRIMARY KEY,fecha DATE NOT NULL,cliente VARCHAR(180) NOT NULL,producto VARCHAR(100) NOT NULL,cantidad_m3 DECIMAL(10,2) NOT NULL,vehiculo VARCHAR(100),piloto VARCHAR(150),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
